<script setup lang="ts">
import {watch} from 'vue'
import {addMonthlyAllowance,type AllowancePreset} from '../fullAttendanceEstimate'
import {newWageEvidence} from '../annualWages'
import WageEventFields from './WageEventFields.vue'
import {useI18n} from 'vue-i18n'
import {usePayrollText} from '../payrollText'
import type {PayItem,SourceRef} from '../payrollTypes'
const props=defineProps<{items:PayItem[];disabled?:boolean;recurring?:boolean;preserveItemIds?:boolean;sources?:SourceRef[];month?:string}>(),{locale}=useI18n(),{r}=usePayrollText()
watch(()=>props.items,items=>{for(const item of items)if(!props.preserveItemIds&&!item.itemId)item.itemId=crypto.randomUUID()},{immediate:true,deep:true})
function isEncash(item:PayItem){return item.eventEvidence?.businessType==='leave_encashment'}
function changeKind(item:PayItem){if(item.kind==='wage_event'){if(!item.eventEvidence)item.eventEvidence=newWageEvidence(props.month);delete item.proration}else delete item.eventEvidence;if(props.recurring&&['ow_allowance','ow_additional','ow_accommodation','ow_attendance'].includes(item.kind))item.proration='full';else delete item.proration}
function chooseSource(item:PayItem,event:Event){const id=(event.target as HTMLSelectElement).value;const ref=props.sources?.find(s=>s.evidence?.eventIds.includes(id));if(!ref){delete item.source;return}item.source={origin:'approved_work',sourceId:ref.sourceId,version:ref.sourceVersion,eventId:id,independentReason:item.source?.independentReason||''}}
function add(){if(props.items.length<20)props.items.push({itemId:crypto.randomUUID(),label:'',kind:'ow_allowance',amount:'',...(props.recurring?{proration:'full' as const}:{})})}
</script>
<template><div class="wf-pay-items"><p class="wf-hint">{{r('itemHint')}}</p><div v-if="recurring" class="wf-inline"><button v-for="preset in (['duty','housing','attendance','other'] as AllowancePreset[])" :key="preset" type="button" :disabled="disabled||items.length>=20" @click="addMonthlyAllowance(items,preset,locale.startsWith('en'))">+ {{({duty:locale.startsWith('en')?'Duty allowance':'职务津贴',housing:locale.startsWith('en')?'Cash housing':'现金住宿津贴',attendance:locale.startsWith('en')?'Attendance bonus':'全勤奖',other:locale.startsWith('en')?'Other allowance':'其他月津贴'})[preset]}}</button></div><article v-for="(item,index) in items" :key="index" class="wf-pay-item"><div class="wf-grid"><label>{{r('itemLabel')}}<input v-model="item.label" required maxlength="100" :disabled="disabled||isEncash(item)"></label></div><p v-if="item.kind==='ow_attendance'" class="wf-hint">{{locale.startsWith('en')?'Actual payroll requires reviewed monthly eligibility; unsettled eligibility blocks month-end confirmation. No monthly bonus is paid in early segments.':'正式工资按本月核准全勤资格判断；资格未知不能月底确认。提前分段暂不发月全勤奖。'}}</p><div class="wf-inline"><label>{{r('amount')}}<input v-model="item.amount" required inputmode="decimal" pattern="\d{1,9}(\.\d{1,2})?" :disabled="disabled||isEncash(item)"></label><button type="button" :disabled="disabled||isEncash(item)" @click="items.splice(index,1)">{{r('remove')}}</button></div><details><summary>{{item.kind==='wage_event'?(locale.startsWith('en')?'Wage event':'工资事项'):r(item.kind)}} · {{locale.startsWith('en')?'Item rules and proration':'项目规则与折算'}}</summary><label>{{r('kind')}}<select v-model="item.kind" @change="changeKind(item)" :disabled="disabled||isEncash(item)"><option v-if="!recurring" value="wage_event">{{locale.startsWith('zh')?'奖金／AWS／工资事项':'Bonus / AWS / wage event'}}</option><option v-if="recurring||item.kind==='ow_attendance'" value="ow_attendance">{{locale.startsWith('en')?'Monthly full-attendance bonus':'月全勤奖（按核准资格）'}}</option><option value="ow_additional">{{r('ow_additional')}}</option><option value="ow_accommodation">{{r('ow_accommodation')}}</option><option value="cdac">{{r('cdacManualItem')}}</option><option value="ow_allowance">{{r('ow_allowance')}}</option><option value="reimbursement">{{r('reimbursement')}}</option><option value="deduction">{{r('deduction')}}</option><option value="employer_charge">{{r('employer_charge')}}</option></select></label><label v-if="recurring&&['ow_allowance','ow_additional','ow_accommodation','ow_attendance'].includes(item.kind)">{{r('proration')}}<select v-model="item.proration" :disabled="disabled||isEncash(item)"><option :value="undefined">{{r('prorationLegacy')}}</option><option value="full">{{r('prorationFull')}}</option><option value="payable">{{r('prorationPayable')}}</option></select></label></details><button v-if="item.kind==='wage_event'&&!item.eventEvidence&&!recurring" type="button" :disabled="disabled||isEncash(item)" @click="item.eventEvidence=newWageEvidence(month)">{{locale.startsWith('zh')?'补充工资事项凭证':'Add missing wage evidence'}}</button><WageEventFields v-if="item.kind==='wage_event'&&item.eventEvidence" :value="item.eventEvidence" :disabled="disabled||recurring"/><p v-if="recurring&&item.kind==='wage_event'" role="alert">{{locale.startsWith('zh')?'工资事项不能写入经常性模板；请建立月度申请。':'Wage events cannot be recurring; create a monthly request.'}}</p><template v-if="item.kind==='deduction'&&sources?.length"><label>{{locale.startsWith('zh')?'事件来源（独立扣款须说明）':'Event source (explain independent deduction)'}}<select :value="item.source?.eventId||''" @change="chooseSource(item,$event)" :disabled="disabled||isEncash(item)"><option value="">{{locale.startsWith('zh')?'无事件引用的人工项目':'Manual item without event reference'}}</option><template v-for="s in sources" :key="s.sourceId"><option v-for="event in s.evidence?.eventIds||[]" :key="event" :value="event">{{s.workDate}} · {{event}}</option></template></select></label><label v-if="item.source">{{locale.startsWith('zh')?'独立扣款原因（工时已折减，不可重复扣减）':'Independent reason (hours already reduced)'}}<textarea v-model="item.source.independentReason" required maxlength="500" :disabled="disabled||isEncash(item)"/></label></template></article><button type="button" :disabled="disabled||items.length>=20" @click="add">{{r('addItem')}}</button></div></template>
